1	import { randomBytes, scrypt as _scrypt, timingSafeEqual, createHash } from "node:crypto";
2	import { promisify } from "node:util";
3	import { cookies } from "next/headers";
4	import { db } from "./db";
5	
6	const scrypt = promisify(_scrypt) as (
7	  password: string,
8	  salt: Buffer,
9	  keylen: number,
10	) => Promise<Buffer>;
11	
12	const SESSION_COOKIE = "kodely_session";
13	const SESSION_DAYS = 30;
14	
15	export async function hashPassword(password: string): Promise<string> {
16	  const salt = randomBytes(16);
17	  const key = await scrypt(password, salt, 64);
18	  return `scrypt$${salt.toString("hex")}$${key.toString("hex")}`;
19	}
20	
21	export async function verifyPassword(password: string, stored: string): Promise<boolean> {
22	  const [scheme, saltHex, keyHex] = stored.split("$");
23	  if (scheme !== "scrypt" || !saltHex || !keyHex) return false;
24	  const key = await scrypt(password, Buffer.from(saltHex, "hex"), 64);
25	  const expected = Buffer.from(keyHex, "hex");
26	  if (key.length !== expected.length) return false;
27	  return timingSafeEqual(key, expected);
28	}
29	
30	// Session tokens are stored hashed, so a database read never yields a usable cookie.
31	function hashToken(token: string) {
32	  return createHash("sha256").update(token).digest("hex");
33	}
34	
35	export async function createSession(userId: string) {
36	  const token = randomBytes(32).toString("base64url");
37	  const expiresAt = new Date(Date.now() + SESSION_DAYS * 86_400_000);
38	  await db.session.create({ data: { userId, tokenHash: hashToken(token), expiresAt } });
39	
40	  const jar = await cookies();
41	  jar.set(SESSION_COOKIE, token, {
42	    httpOnly: true,
43	    sameSite: "lax",
44	    secure: process.env.NODE_ENV === "production",
45	    path: "/",
46	    expires: expiresAt,
47	  });
48	}
49	
50	export async function destroySession() {
51	  const jar = await cookies();
52	  const token = jar.get(SESSION_COOKIE)?.value;
53	  if (token) await db.session.deleteMany({ where: { tokenHash: hashToken(token) } });
54	  jar.delete(SESSION_COOKIE);
55	}
56	
57	export async function getCurrentUser() {
58	  const jar = await cookies();
59	  const token = jar.get(SESSION_COOKIE)?.value;
60	  if (!token) return null;
61	
62	  const session = await db.session.findUnique({
63	    where: { tokenHash: hashToken(token) },
64	    include: { user: true },
65	  });
66	  if (!session || session.expiresAt < new Date()) return null;
67	  return session.user;
68	}
69	
70	/**
71	 * The Session ROW behind the current cookie, rather than the user on it.
72	 *
73	 * Additive: nothing that existed before this function behaves differently.
74	 *
75	 * It exists because a sessions list has to be able to say "this is the one you
76	 * are using" and a revoke route has to refuse to cut its own caller off, and
77	 * both of those need the session id — which `getCurrentUser` deliberately
78	 * throws away. The alternative was to re-derive it at the call site, which
79	 * means copying SESSION_COOKIE and hashToken out of this file. A settings
80	 * screen that quietly disagrees with the real cookie name would mark the wrong
81	 * row as "this device", and there is no worse lie to tell on a security page.
82	 *
83	 * Same expiry rule as getCurrentUser: an expired row resolves to null rather
84	 * than to a session, so the two can never disagree about being signed in.
85	 */
86	export async function getCurrentSession() {
87	  const jar = await cookies();
88	  const token = jar.get(SESSION_COOKIE)?.value;
89	  if (!token) return null;
90	
91	  const session = await db.session.findUnique({ where: { tokenHash: hashToken(token) } });
92	  if (!session || session.expiresAt < new Date()) return null;
93	  return session;
94	}
95	
96	export async function requireUser() {
97	  const user = await getCurrentUser();
98	  if (!user) throw new Error("UNAUTHENTICATED");
99	  return user;
100	}
101	
102	/**
103	 * Signed in AND role === "ADMIN". Returns null otherwise — callers decide
104	 * between a 404 and a redirect rather than getting a thrown error.
105	 *
106	 * app/admin/layout.tsx already gates the admin section, and that check is the
107	 * real one. This exists so each admin PAGE and API route can assert the same
108	 * thing itself: Next's own guidance is not to treat a layout as the sole
109	 * authorization boundary, since layouts don't re-render on every navigation
110	 * within a section and route handlers don't sit under them at all. Belt and
111	 * braces on a page showing cost, margin, and customer prompts.
112	 */
113	export async function getAdminUser() {
114	  const user = await getCurrentUser();
115	  return user && user.role === "ADMIN" ? user : null;
116	}
