59	          <Link href="/" onClick={() => setOpen(false)}>
60	            <Logo markSize={22} className="text-[15px]" />
61	          </Link>
62	
63	          <nav aria-label="Main" className="hidden items-center gap-7 text-sm sm:flex">
64	            {LINKS.map((link) => {
