71	                  // underline only — nothing a screen reader could hear.
72	                  aria-current={active ? "page" : undefined}
73	                  className={`relative py-1 transition-colors ${
74	                    active
75	                      ? "text-neutral-900 dark:text-white"
76	                      : "text-neutral-600 hover:text-neutral-900 dark:text-neutral-400 dark:hover:text-white"
77	                  }`}
78	                >
79	                  {link.label}
80	                  {active && (
81	                    <span
82	                      aria-hidden
83	                      className="absolute -bottom-1 left-0 right-0 h-px"
84	                      style={{ background: "var(--brand-gradient)" }}
85	                    />
86	                  )}
87	                </Link>
88	              );
89	            })}
90	            <ThemeToggle />
91	            <ShineButton>
92	              <Link
93	                href="/signup"
94	                className="inline-block rounded-lg bg-neutral-900 px-4 py-2 text-sm font-medium text-white dark:bg-white dark:text-neutral-900"
95	              >
96	                Get started
97	              </Link>
98	            </ShineButton>
99	          </nav>
100	
101	          <div className="flex items-center gap-2 sm:hidden">
102	            <ThemeToggle />
103	            <button
104	              ref={toggleRef}
105	              type="button"
106	              onClick={() => setOpen((v) => !v)}
107	              className="rounded-md p-2 text-neutral-700 dark:text-neutral-300"
108	              // Open/closed was conveyed only by swapping the icon glyph.
109	              // aria-expanded + aria-controls state it properly, and the
110	              // label now says what pressing it will do.
111	              aria-label={open ? "Close menu" : "Open menu"}
112	              aria-expanded={open}
