115	              {open ? <X size={20} /> : <Menu size={20} />}
116	            </button>
117	          </div>
118	        </div>
119	
120	        <AnimatePresence>
121	          {open && (
122	            <motion.nav
123	              id="mobile-nav"
124	              aria-label="Main"
125	              initial={{ height: 0, opacity: 0 }}
126	              animate={{ height: "auto", opacity: 1 }}
127	              exit={{ height: 0, opacity: 0 }}
128	              transition={{ duration: 0.25, ease: [0.16, 1, 0.3, 1] }}
129	              className="overflow-hidden sm:hidden"
130	            >
131	              <div className="mt-2 flex flex-col gap-1 border-t border-neutral-200/70 px-2 pt-3 text-sm dark:border-neutral-800/70">
132	                {LINKS.map((link) => (
133	                  <Link
134	                    key={link.href}
135	                    href={link.href}
136	                    onClick={() => setOpen(false)}
137	                    aria-current={pathname === link.href ? "page" : undefined}
138	                    className="rounded-md px-2 py-2.5 text-neutral-700 hover:bg-neutral-100 dark:text-neutral-300 dark:hover:bg-neutral-900"
139	                  >
140	                    {link.label}
141	                  </Link>
142	                ))}
143	                <Link
144	                  href="/signup"
145	                  onClick={() => setOpen(false)}
146	                  className="mt-2 rounded-lg bg-neutral-900 px-4 py-2.5 text-center text-sm font-medium text-white dark:bg-white dark:text-neutral-900"
147	                >
148	                  Get started
149	                </Link>
