1	import { db } from "@/lib/db";
2	import { verifyPassword, createSession } from "@/lib/auth";
3	import { checkLoginRateLimit, noteLoginSuccess, RATE_LIMITED_MESSAGE } from "@/lib/rate-limit";
4	
5	export const dynamic = "force-dynamic";
6	
7	// A syntactically valid hash that no password can ever match: same scheme and
8	// the same 16-byte salt / 64-byte key lengths as lib/auth.ts writes, so
9	// verifyPassword does its full scrypt derivation and then fails the compare.
10	//
11	// It exists so the "no such account" path costs the same as the "wrong
12	// password" path. Without it, verifyPassword is skipped entirely when the email
13	// is unknown and the route answers in a millisecond instead of ~100ms — a clean
14	// oracle for whether an address is registered, which would undo the constant
15	// SHAPE the response body already keeps.
16	const ABSENT_ACCOUNT_HASH = `scrypt$${"00".repeat(16)}$${"00".repeat(64)}`;
17	
18	export async function POST(req: Request) {
19	  const body = (await req.json().catch(() => null)) as
20	    | { email?: string; password?: string }
21	    | null;
22	  const email = body?.email?.trim().toLowerCase();
23	  const password = body?.password;
24	  if (!email || !password) {
25	    return Response.json({ error: "Enter your email and password." }, { status: 400 });
26	  }
27	
28	  // Before the user lookup and before scrypt: an attacker must not be able to
29	  // spend the server's CPU, or learn anything from the database, past the
30	  // limit. Keyed on the client IP and on the account being targeted — see
31	  // lib/rate-limit.ts for why both, and for which header the IP comes from.
32	  const gate = checkLoginRateLimit(req, email);
33	  if (!gate.allowed) {
34	    return Response.json(
35	      { error: RATE_LIMITED_MESSAGE },
36	      {
37	        status: 429,
38	        headers: { "Retry-After": String(gate.retryAfterSeconds ?? 60) },
39	      },
40	    );
41	  }
42	
43	  const user = await db.user.findUnique({ where: { email } });
44	  // Constant-shape response whether or not the account exists, to avoid
45	  // leaking which emails are registered. A Google-only account has no local
46	  // password to check against — it never verifies here (correctly, they
47	  // must use "Continue with Google" instead), and takes the same decoy hash
48	  // as a nonexistent account so it costs the same time too.
49	  const ok =
50	    (await verifyPassword(password, user?.passwordHash ?? ABSENT_ACCOUNT_HASH)) &&
51	    Boolean(user?.passwordHash);
52	  if (!user || !ok) {
53	    return Response.json({ error: "Incorrect email or password." }, { status: 401 });
54	  }
55	
56	  // Proof of the password: hand back what this attempt cost the limiter, so
57	  // ordinary sign-ins never accumulate toward a throttle.
58	  noteLoginSuccess(req, email);
59	
60	  await createSession(user.id);
61	  return Response.json({ id: user.id, email: user.email });
62	}
