1	import { db } from "@/lib/db";
2	import { hashPassword, createSession } from "@/lib/auth";
3	import { grantCredits, SIGNUP_GRANT } from "@/lib/credits";
4	import { createSeedProject } from "@/lib/seed-project";
5	import { track, EVENTS } from "@/lib/events";
6	import { checkSignupRateLimit, RATE_LIMITED_MESSAGE } from "@/lib/rate-limit";
7	import { FLAGS, isEnabled } from "@/lib/flags";
8	
9	export const dynamic = "force-dynamic";
10	
11	const EMAIL_RE = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
12	
13	export async function POST(req: Request) {
14	  const body = (await req.json().catch(() => null)) as
15	    | { email?: string; password?: string; name?: string }
16	    | null;
17	
18	  const email = body?.email?.trim().toLowerCase();
19	  const password = body?.password;
20	
21	  if (!email || !EMAIL_RE.test(email)) {
22	    return Response.json({ error: "Enter a valid email." }, { status: 400 });
23	  }
24	  if (!password || password.length < 8) {
25	    return Response.json({ error: "Password must be at least 8 characters." }, { status: 400 });
26	  }
27	
28	  // ── Kill switch ──────────────────────────────────────────────────────────
29	  // After the shape checks (a malformed body still gets the specific answer
30	  // that tells the person how to fix it) and before everything with a side
31	  // effect: the rate-limit counter that `record()`s a hit against this IP, the
32	  // existence lookup, db.user.create, the SIGNUP_GRANT of real model spend, the
33	  // seed project and the session cookie. A refused signup leaves no user row,
34	  // no ledger row, no project and no session.
35	  //
36	  // Ahead of the existence check on purpose. That 409 is the only response on
37	  // this route that differs for a registered address, i.e. the enumeration
38	  // oracle the rate limiter above exists to bound. A route that cannot create
39	  // an account has no business still answering it.
40	  //
41	  // ANONYMOUS BY NATURE — there is no subject id to pass, because the whole
42	  // point is that this person has no account yet. Per lib/flags.ts, a check
43	  // with no subject resolves to false for ANY rolloutPct below 100, so a
44	  // half-set percentage here is not a half-rollout, it is a full stop. This
45	  // flag must be operated at rolloutPct 100 and toggled with `enabled` — which
46	  // is how a kill switch is meant to be operated anyway. The same note is on
47	  // the Google callback, the other half of this switch.
48	  if (!(await isEnabled(FLAGS.signups))) {
49	    return Response.json(
50	      {
51	        error:
52	          "New sign-ups are paused right now. No account was created — please try again a little later.",
53	      },
54	      { status: 503 },
55	    );
56	  }
57	
58	  // Deliberately AFTER the shape checks — a malformed body never created an
59	  // account, so there is nothing to meter — but BEFORE the existence check
60	  // below, which is the only response on this route that differs for a
61	  // registered address and is therefore an enumeration oracle. One counter now
62	  // bounds both that and the thing that actually costs money: every account
63	  // that lands here is immediately granted SIGNUP_GRANT credits of real model
64	  // spend. Keyed per client IP; see lib/rate-limit.ts for the header choice.
65	  const gate = checkSignupRateLimit(req);
66	  if (!gate.allowed) {
67	    return Response.json(
68	      { error: RATE_LIMITED_MESSAGE },
69	      {
70	        status: 429,
71	        headers: { "Retry-After": String(gate.retryAfterSeconds ?? 60) },
72	      },
73	    );
74	  }
75	
76	  const existing = await db.user.findUnique({ where: { email } });
77	  if (existing) {
78	    return Response.json({ error: "An account with that email already exists." }, { status: 409 });
79	  }
80	
81	  const user = await db.user.create({
82	    data: { email, passwordHash: await hashPassword(password), name: body?.name?.trim() || null },
83	  });
84	
85	  await grantCredits(user.id, SIGNUP_GRANT, "signup_grant");
86	  await createSeedProject(user.id);
87	  await createSession(user.id);
88	
89	  track(EVENTS.signedUp, { userId: user.id, props: { method: "password" } });
90	
91	  return Response.json({ id: user.id, email: user.email });
92	}
