// End-to-end check of the auth-hint cookie lifecycle against a running dev
// server. Creates a throwaway user directly (bypassing /api/auth/signup so no
// credits/seed project/events are produced) and deletes it at the end.
import { PrismaClient } from "@prisma/client";
import { randomBytes, scrypt as _scrypt, createHash } from "node:crypto";
import { promisify } from "node:util";

const scrypt = promisify(_scrypt);
const BASE = "http://localhost:3000";
const db = new PrismaClient();

const EMAIL = `hint-e2e-${Date.now()}@example.invalid`;
const PASSWORD = "correct-horse-battery-staple";

let failures = 0;
function check(name, cond, detail = "") {
  const ok = Boolean(cond);
  if (!ok) failures++;
  console.log(`${ok ? "PASS" : "FAIL"}  ${name}${detail ? `\n        ${detail}` : ""}`);
}

function setCookies(res) {
  return typeof res.headers.getSetCookie === "function" ? res.headers.getSetCookie() : [];
}
function cookieNamed(list, name) {
  return list.find((c) => c.split("=")[0].trim() === name) ?? null;
}
function isDeletion(str) {
  if (!str) return false;
  const s = str.toLowerCase();
  return /expires=thu, 01 jan 1970/.test(s) || /max-age=0/.test(s) || /(^|;\s*)[^=]+=;/.test(str);
}

async function hashPassword(password) {
  const salt = randomBytes(16);
  const key = await scrypt(password, salt, 64);
  return `scrypt$${salt.toString("hex")}$${key.toString("hex")}`;
}

async function main() {
  const user = await db.user.create({
    data: { email: EMAIL, passwordHash: await hashPassword(PASSWORD) },
  });

  // ── 1. sign in ───────────────────────────────────────────────────────────
  const login = await fetch(`${BASE}/api/auth/login`, {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({ email: EMAIL, password: PASSWORD }),
    redirect: "manual",
  });
  const loginCookies = setCookies(login);
  const sessionSet = cookieNamed(loginCookies, "kodely_session");
  const hintSet = cookieNamed(loginCookies, "kodely_auth");

  check("sign-in returns 200", login.status === 200, `status=${login.status}`);
  check("sign-in sets kodely_session", Boolean(sessionSet));
  check("sign-in sets kodely_auth", Boolean(hintSet), hintSet ?? "");

  check("session cookie is HttpOnly", /httponly/i.test(sessionSet ?? ""));
  check("hint cookie is NOT HttpOnly (JS must read it)", !/httponly/i.test(hintSet ?? ""));
  check("hint cookie is SameSite=Lax", /samesite=lax/i.test(hintSet ?? ""));
  check("hint cookie is Path=/", /path=\//i.test(hintSet ?? ""));
  check("hint cookie carries an Expires", /expires=/i.test(hintSet ?? ""));
  check(
    "hint cookie value is the single literal '1' — no identity, no email, no token",
    /^kodely_auth=1(;|$)/.test(hintSet ?? ""),
    hintSet ?? "",
  );
  check(
    "hint cookie leaks no email / user id / session token",
    !(hintSet ?? "").includes(EMAIL) &&
      !(hintSet ?? "").includes(user.id) &&
      !(hintSet ?? "").includes((sessionSet ?? "").split("=")[1]?.split(";")[0] ?? "�"),
  );

  // Expiries line up so the browser drops both in the same instant.
  const sessionExp = /expires=([^;]+)/i.exec(sessionSet ?? "")?.[1];
  const hintExp = /expires=([^;]+)/i.exec(hintSet ?? "")?.[1];
  check("hint expiry equals session expiry", sessionExp === hintExp, `${sessionExp} vs ${hintExp}`);

  const days = (new Date(sessionExp) - Date.now()) / 86_400_000;
  check("session expiry is ~30 days out", days > 29.9 && days < 30.1, `${days.toFixed(3)} days`);

  const jar = `kodely_session=${(sessionSet ?? "").split("=")[1].split(";")[0]}; kodely_auth=1`;
  const sessionOnly = `kodely_session=${(sessionSet ?? "").split("=")[1].split(";")[0]}`;

  // ── 2. hard 30 days, or sliding? ─────────────────────────────────────────
  const rowBefore = await db.session.findFirst({
    where: { userId: user.id },
    orderBy: { createdAt: "desc" },
  });
  await fetch(`${BASE}/templates`, { headers: { cookie: jar } });
  await fetch(`${BASE}/api/auth/me`, { headers: { cookie: jar } });
  const rowAfter = await db.session.findUnique({ where: { id: rowBefore.id } });
  check(
    "session expiry is NOT extended by activity (hard 30 days from sign-in)",
    rowBefore.expiresAt.getTime() === rowAfter.expiresAt.getTime(),
    `before=${rowBefore.expiresAt.toISOString()} after=${rowAfter.expiresAt.toISOString()}`,
  );

  // ── 3. a DYNAMIC marketing page renders the signed-in nav server-side ────
  const templates = await fetch(`${BASE}/templates`, { headers: { cookie: jar } });
  const templatesHtml = await templates.text();
  check("dynamic /templates HTML contains 'Portal'", templatesHtml.includes(">Portal<"));
  check(
    "dynamic /templates HTML contains 'Create website'",
    templatesHtml.includes("Create website"),
  );
  check(
    "dynamic /templates HTML no longer offers 'Sign in' / 'Get started'",
    !templatesHtml.includes(">Sign in<") && !templatesHtml.includes(">Get started<"),
  );
  check(
    "dynamic /templates links Portal at /dashboard and the CTA at /dashboard/new",
    templatesHtml.includes('href="/dashboard"') && templatesHtml.includes('href="/dashboard/new"'),
  );

  // Signed OUT, the same page is unchanged.
  const anonTemplates = await (await fetch(`${BASE}/templates`)).text();
  check(
    "signed-out /templates is unchanged: 'Sign in' + 'Get started'",
    anonTemplates.includes(">Sign in<") && anonTemplates.includes(">Get started<"),
  );
  check("signed-out /templates offers no Portal", !anonTemplates.includes(">Portal<"));

  // ── 4. a STATIC marketing page ships the signed-out nav (client swaps it) ─
  const pricing = await fetch(`${BASE}/pricing`, { headers: { cookie: jar } });
  const pricingHtml = await pricing.text();
  check(
    "static /pricing still server-renders the signed-out nav (the accepted flash)",
    pricingHtml.includes(">Sign in<"),
  );
  check(
    "static /pricing emits no Set-Cookie when the two cookies agree (stays cacheable)",
    setCookies(pricing).length === 0,
    JSON.stringify(setCookies(pricing)),
  );

  // ── 5. proxy backfill: a session that predates the feature ───────────────
  const legacy = await fetch(`${BASE}/pricing`, { headers: { cookie: sessionOnly } });
  const legacySet = cookieNamed(setCookies(legacy), "kodely_auth");
  check("proxy backfills a missing hint for an existing session", Boolean(legacySet), legacySet ?? "");
  check("backfilled hint is the literal '1'", /^kodely_auth=1(;|$)/.test(legacySet ?? ""));
  check("backfilled hint is not HttpOnly", !/httponly/i.test(legacySet ?? ""));

  // ── 6. proxy repair: a STALE hint with no session ────────────────────────
  const stale = await fetch(`${BASE}/pricing`, { headers: { cookie: "kodely_auth=1" } });
  const staleSet = cookieNamed(setCookies(stale), "kodely_auth");
  check("proxy clears a hint whose session cookie is gone", isDeletion(staleSet), staleSet ?? "none");
  check("the clearing cookie is Path=/ so it actually deletes", /path=\//i.test(staleSet ?? ""));

  // ── 7. anonymous traffic is never touched ────────────────────────────────
  const anon = await fetch(`${BASE}/pricing`);
  check(
    "an anonymous request gets no Set-Cookie at all",
    setCookies(anon).length === 0,
    JSON.stringify(setCookies(anon)),
  );
  const anonBlog = await fetch(`${BASE}/blog`);
  check("anonymous /blog gets no Set-Cookie either", setCookies(anonBlog).length === 0);

  // ── 8. /login and /signup bounce an already-signed-in visitor ────────────
  for (const path of ["/login", "/signup"]) {
    const res = await fetch(`${BASE}${path}`, { headers: { cookie: jar }, redirect: "manual" });
    check(
      `signed-in ${path} redirects to /continue`,
      [307, 308, 302].includes(res.status) && (res.headers.get("location") ?? "").endsWith("/continue"),
      `status=${res.status} location=${res.headers.get("location")}`,
    );
    const anonRes = await fetch(`${BASE}${path}`, { redirect: "manual" });
    check(`signed-out ${path} still renders the form`, anonRes.status === 200, `status=${anonRes.status}`);
  }

  // ── 9. SIGN OUT — the failure mode this feature has to get right ─────────
  const logout = await fetch(`${BASE}/api/auth/logout`, {
    method: "POST",
    headers: { cookie: jar },
    redirect: "manual",
  });
  const outCookies = setCookies(logout);
  const sessionCleared = cookieNamed(outCookies, "kodely_session");
  const hintCleared = cookieNamed(outCookies, "kodely_auth");
  check("sign-out clears kodely_session", isDeletion(sessionCleared), sessionCleared ?? "none");
  check("sign-out clears kodely_auth", isDeletion(hintCleared), hintCleared ?? "none");
  check("the hint deletion is Path=/", /path=\//i.test(hintCleared ?? ""));

  const rowsLeft = await db.session.count({ where: { userId: user.id } });
  check("sign-out deleted the session row", rowsLeft === 0, `rows=${rowsLeft}`);

  // After sign-out the old jar is worthless everywhere.
  const afterOut = await (await fetch(`${BASE}/templates`, { headers: { cookie: sessionOnly } })).text();
  check(
    "a revoked session no longer renders the signed-in nav",
    afterOut.includes(">Sign in<") && !afterOut.includes(">Portal<"),
  );
  const meAfter = await (await fetch(`${BASE}/api/auth/me`, { headers: { cookie: jar } })).json();
  check("/api/auth/me reports signed out after sign-out", meAfter.user === null);

  // ── 10. an EXPIRED session row resolves to signed-out ────────────────────
  const token = randomBytes(32).toString("base64url");
  await db.session.create({
    data: {
      userId: user.id,
      tokenHash: createHash("sha256").update(token).digest("hex"),
      expiresAt: new Date(Date.now() - 60_000),
    },
  });
  const expiredJar = `kodely_session=${token}; kodely_auth=1`;
  const expiredMe = await (await fetch(`${BASE}/api/auth/me`, { headers: { cookie: expiredJar } })).json();
  check("an expired session row reads as signed out", expiredMe.user === null);
  const expiredHtml = await (await fetch(`${BASE}/templates`, { headers: { cookie: expiredJar } })).text();
  check(
    "an expired session shows the signed-out nav on a dynamic page",
    expiredHtml.includes(">Sign in<") && !expiredHtml.includes(">Portal<"),
  );
  const stillThere = await db.session.count({
    where: { userId: user.id, expiresAt: { lt: new Date() } },
  });
  check(
    "NOTE: the expired row is NOT deleted — nothing prunes it",
    stillThere === 1,
    `expired rows still in the table: ${stillThere}`,
  );

  await db.session.deleteMany({ where: { userId: user.id } });
  await db.user.delete({ where: { id: user.id } });
  console.log(`\n${failures === 0 ? "ALL CHECKS PASSED" : `${failures} CHECK(S) FAILED`}`);
  await db.$disconnect();
  process.exit(failures === 0 ? 0 : 1);
}

